#include "prop_physics.hpp"
#include "replay.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
static void check(bool value,const char*message){if(!value)throw std::runtime_error(message);}
int main(){try{
 btDefaultCollisionConfiguration config;btCollisionDispatcher dispatcher(&config);btDbvtBroadphase broadphase;btSequentialImpulseConstraintSolver solver;ContactWorld world(&dispatcher,&broadphase,&solver,&config);world.setGravity({0,0,0});
 PropDefinition def;def.mass=40;def.inertia={7,7,7};def.transform=translate({0,5,0});PropDefinition other=def;other.transform=translate({10,5,0});PropPhysics props(world,{def,other});
 auto empty=props.snapshot();check(empty&&empty->empty(),"held snapshots remain sparse");check(props.snapshot()==empty,"unchanged empty snapshots reuse storage");
 btSphereShape shape(.5f);btRigidBody::btRigidBodyConstructionInfo ci(80,nullptr,&shape,{8,8,8});btRigidBody actor(ci);btTransform at;at.setIdentity();at.setOrigin({-.9f,5,0});actor.setWorldTransform(at);actor.setLinearVelocity({2,0,0});world.addRigidBody(&actor,2,4|16);world.performDiscreteCollisionDetection();check(props.activate_contacts(&actor,nullptr),"moving car impact releases prop");
 auto first=props.snapshot();check(first->size()==1&&first->at(0).transform==def.transform,"new release publishes exact transform");check(first!=empty&&empty->empty(),"old sparse snapshot remains immutable");check(props.snapshot()==first,"unchanged released snapshots reuse storage");
 // Changing a body through Bullet must publish a fresh snapshot, even when asleep.
 btRigidBody*prop=nullptr;for(int i=0;i<world.getNumCollisionObjects();++i){auto*body=btRigidBody::upcast(world.getCollisionObjectArray()[i]);if(body!=&actor&&body->getInvMass()>0)prop=body;}
 check(prop!=nullptr,"released body remains in world");auto moved=prop->getWorldTransform();moved.setOrigin({3,5,0});prop->setWorldTransform(moved);prop->forceActivationState(ISLAND_SLEEPING);auto second=props.snapshot();check(second!=first&&second->at(0).transform[12]==3,"sleeping body movement publishes new transform");check(first->at(0).transform[12]==0,"previous replay snapshot stays immutable");check(props.snapshot()==second,"stationary sleeping snapshot reuse");
 at.setOrigin({9.1f,5,0});actor.setWorldTransform(at);world.updateSingleAabb(&actor);world.performDiscreteCollisionDetection();check(props.activate_contacts(&actor,nullptr),"second moving impact releases new prop");auto third=props.snapshot();check(third->size()==2&&third->at(0).transform[12]==3&&third->at(1).transform[12]==10,"new release preserves existing immutable prefix");
 btRigidBody*second_prop=nullptr;for(int i=0;i<world.getNumCollisionObjects();++i){auto*body=btRigidBody::upcast(world.getCollisionObjectArray()[i]);if(body!=&actor&&body!=prop)second_prop=body;}check(second_prop!=nullptr,"second prop remains in world");moved=second_prop->getWorldTransform();moved.setOrigin({14,5,0});second_prop->setWorldTransform(moved);auto fourth=props.snapshot();check(fourth!=third&&fourth->at(0).transform[12]==3&&fourth->at(1).transform[12]==14,"late changed transform preserves cached prefix");check(third->at(1).transform[12]==10,"earlier multi-prop snapshot stays immutable");world.removeRigidBody(&actor);
 Replay replay;State state;state.props=std::make_shared<const std::vector<PropPose>>(1500);for(int i=0;i<1800;++i){state.time=i*.01;replay.record(state);}check(replay.diagnostics().at("frames")==1800,"shared stationary snapshot must not evict replay frames");check(replay.diagnostics().at("bytes").get<size_t>()==1800*sizeof(State)+1500*sizeof(PropPose),"replay charges contiguous shared prop snapshot once");replay.begin();check(replay.sample().time==0,"shared snapshot retains first frame");
 // Crossing a run boundary must drop the old payload only after its final frame.
 state.props=std::make_shared<const std::vector<PropPose>>(1500);for(int i=0;i<59000;++i)replay.record(state);check(replay.diagnostics().at("frames")==60000,"frame cap remains bounded with shared snapshots");check(replay.diagnostics().at("bytes").get<size_t>()==60000*sizeof(State)+3000*sizeof(PropPose),"partial first run eviction keeps its payload charged");for(int i=0;i<1000;++i)replay.record(state);check(replay.diagnostics().at("bytes").get<size_t>()==60000*sizeof(State)+1500*sizeof(PropPose),"final first run eviction releases its payload charge");
 replay.clear();check(replay.diagnostics().at("bytes")==0,"replay clear resets memory accounting");
 Replay damageReplay;State damaged;damaged.impacts=std::make_shared<const std::vector<VehicleDamageContact>>(32);damaged.collision_contacts=std::make_shared<const std::vector<VehicleDamageContact>>(3);damaged.panels=std::make_shared<const std::vector<VehiclePanelPose>>(8);damaged.collision_events=std::make_shared<const std::vector<CollisionEvent>>(128);damaged.driver_bones=std::make_shared<const std::array<Mat,11>>();for(int i=0;i<10;i++)damageReplay.record(damaged);check(damageReplay.diagnostics().at("bytes").get<size_t>()==10*sizeof(State)+35*sizeof(VehicleDamageContact)+8*sizeof(VehiclePanelPose)+128*sizeof(CollisionEvent)+11*sizeof(Mat),"damage and panel immutable payloads charged once per run");
 std::cout<<"immutable prop snapshot reuse and shared replay budget passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
